int parse_rose_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int bytes_processed = 0;
    unsigned char *end = p + len;

    while (p < end && *p != 0x00) {
        unsigned char byte = *p++;
        bytes_processed++;

        switch ((byte >> 6) & 0x03) {
            case 0x00:
                // Type 0 processing
                if (bytes_processed + 1 > len)
                    return -1;

                facilities->source_address = (*p) & 0x0F;
                p++;
                bytes_processed++;
                break;
            case 0x01:
                // Type 1 processing
                if (bytes_processed + 2 > len)
                    return -1;

                facilities->destination_call = (*p << 8) | *(p + 1);
                p += 2;
                bytes_processed += 2;
                break;
            case 0x02:
                // Type 2 processing
                if (bytes_processed + 3 > len)
                    return -1;

                facilities->source_call = (*p << 16) | (*(p + 1) << 8) | *(p + 2);
                p += 3;
                bytes_processed += 3;
                break;
            case 0x03:
                // Type 3 processing
                return bytes_processed;
            default:
                // Invalid type
                return -1;
        }
    }

    return (p >= end) ? -1 : bytes_processed;
}

int parse_rose_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int processed = 0;
    unsigned char *start = p;
    unsigned char *end = p + len;

    while (p < end && *p != 0x00) {
        switch ((*p >> 6) & 0x03) {
            case 0x00:
                /* Reserved, treat as invalid */
                return -1;
            case 0x01:
                p++;
                processed++;
                break;
            case 0x02:
                p += 2;
                processed += 2;
                break;
            case 0x03:
                p += 3;
                processed += 3;
                break;
        }

        if (processed >= len)
            return -1;
    }

    if (p >= end)
        return -1;

    return processed + 1;
}

int parse_ccitt_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int processed = 0;
    unsigned char *end = p + len;

    while (p < end && *p != 0x00) {
        unsigned char byte = *p++;
        processed++;

        switch ((byte >> 6) & 0x03) {
        case 0x00: /* Facility type 00 */
            if (p + 2 > end)
                return -1;
            facilities->source_address = (p[0] << 8) | p[1];
            p += 2;
            processed += 2;
            break;
        case 0x01: /* Facility type 01 */
            if (p + 7 > end)
                return -1;
            facilities->dest_address = (p[0] << 8) | p[1];
            facilities->dest_callsign[0] = p[2];
            facilities->dest_callsign[1] = p[3];
            facilities->dest_callsign[2] = p[4];
            facilities->dest_callsign[3] = p[5];
            p += 7;
            processed += 7;
            break;
        case 0x02: /* Facility type 10 */
            if (p + 7 > end)
                return -1;
            facilities->source_callsign[0] = p[0];
            facilities->source_callsign[1] = p[1];
            facilities->source_callsign[2] = p[2];
            facilities->source_callsign[3] = p[3];
            p += 4;
            processed += 4;
            break;
        case 0x03: /* Facility type 11 */
            /* Reserved or unknown, skip */
            break;
        default:
            return -1;
        }
    }

    if (p >= end && processed < len) {
        return -1;
    }

    return processed;
}

int parse_ccitt_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    int bytes_processed = 0;

    while (bytes_processed < len) {
        unsigned char byte = p[bytes_processed];

        if (byte == 0x00) {
            break;
        }

        int length = byte & 0x0F;
        int type = (byte >> 4) & 0x03;

        if (length == 0) {
            break;
        }

        switch (type) {
            case 0x00: /* Source Address */
                if (length > 0) {
                    facilities->source_address_len = length;
                    memcpy(facilities->source_address, p + bytes_processed + 1, length);
                }
                break;

            case 0x01: /* Destination Address */
                if (length > 0) {
                    facilities->dest_address_len = length;
                    memcpy(facilities->dest_address, p + bytes_processed + 1, length);
                }
                break;

            case 0x02: /* Source Call Sign */
                if (length > 0) {
                    facilities->source_call_len = length;
                    memcpy(facilities->source_call, p + bytes_processed + 1, length);
                }
                break;

            case 0x03: /* Destination Call Sign */
                if (length > 0) {
                    facilities->dest_call_len = length;
                    memcpy(facilities->dest_call, p + bytes_processed + 1, length);
                }
                break;

            default:
                /* Invalid type */
                return -1;
        }

        bytes_processed += length + 1;
    }

    if (bytes_processed > len) {
        return -1;
    }

    return bytes_processed;
}

int parse_rose_facilities(unsigned char *p, struct rose_facilities_struct *facilities, int len) {
    unsigned char *start = p;
    unsigned char *end = p + len;

    while (p < end && *p != 0x00) {
        unsigned char tag = *p++;

        switch ((tag >> 6) & 3) {
            case 0: /* End of processing */
                return p - start;

            case 1: /* Source address */
                if (p + 5 > end)
                    return -1;

                facilities->source_address[0] = *p++;
                facilities->source_address[1] = *p++;
                facilities->source_address[2] = *p++;
                facilities->source_address[3] = *p++;
                facilities->source_address[4] = *p++;
                break;

            case 2: /* Destination address */
                if (p + 5 > end)
                    return -1;

                facilities->dest_address[0] = *p++;
                facilities->dest_address[1] = *p++;
                facilities->dest_address[2] = *p++;
                facilities->dest_address[3] = *p++;
                facilities->dest_address[4] = *p++;
                break;

            case 3: /* Source call sign */
                if (p + 7 > end)
                    return -1;

                for (int i = 0; i < 7; i++)
                    facilities->source_call[i] = *p++;

                facilities->source_call[7] = '\0';
                break;

            default:
                break;
        }
    }

    if (p >= end)
        return -1;

    return p - start;
}
